  "Süresi dolacak": {"tr":"Süresi dolacak","en":"Expires"},
  "Yeni bilgisayar kayıtları": {"tr":"Yeni bilgisayar kayıtları","en":"New computer registrations"},
  "Yeni yedekleme bilgisayarı eklenebilir.": {"tr":"Yeni yedekleme bilgisayarı eklenebilir.","en":"New backup computers can be added."},
  "Yeni yedekleme bilgisayarı eklenemez.": {"tr":"Yeni yedekleme bilgisayarı eklenemez.","en":"New backup computers cannot be added."},
